import { z } from 'zod';

/**
 * Only fields the API actually stores.
 *
 * The form used to collect role, organisation, bank account, profile
 * picture and a password. None of them exist as columns on `users`, and
 * the password is generated by the API rather than chosen here, so they
 * were dropped rather than silently discarded on submit.
 */
export const createUserSchema = z.object({
  firstName: z.string().min(1, 'First name is required').max(100),
  lastName: z.string().min(1, 'Last name is required').max(100),
  email: z.string().email('Invalid email address'),
  phone: z.string().min(1, 'Phone is required').max(30),
  password: z.string().min(8, 'Password must be at least 8 characters'),
});

/**
 * Phone is not stored and the password is not settable here: changing one
 * goes through the account's own reset flow, not this form.
 */
export const editUserSchema = createUserSchema.omit({
  phone: true,
  password: true,
});

export type UserFormData = z.infer<typeof createUserSchema>;
